<template><section class="mypage-dashboard"><div class="dashboard-head"><div><p class="eyebrow">MY OVERVIEW</p><h2>나의 활동 현황</h2><p>추천 및 구매 현황을 한눈에 확인하세요.</p></div><label>조회 기간<select v-model="selectedMonth"><option value="전체">전체 기간</option><option v-for="month in availableMonths" :key="month" :value="month">{{month}}</option></select></label></div><div v-if="stats" class="stat-grid"><article><span><i class="fa-solid fa-users"></i></span><p>총 추천 회원</p><strong>{{formatNumber(stats.totalRefCount)}}<small>명</small></strong></article><article><span><i class="fa-solid fa-won-sign"></i></span><p>누적 구매 금액</p><strong>{{formatNumber(stats.totalPurchase)}}<small>원</small></strong></article><article><span><i class="fa-regular fa-calendar"></i></span><p>조회 기간</p><strong>{{selectedMonth==='전체'?'전체':selectedMonth}}</strong></article></div><div v-else class="dashboard-loading"><span></span><p>활동 정보를 불러오고 있습니다.</p></div><div class="activity-table"><div class="activity-title"><h3>월별 활동 내역</h3><span>최근 활동부터 표시됩니다.</span></div><div class="table-scroll"><table v-if="stats"><thead><tr><th>년월</th><th>신규 추천 회원</th><th>구매 금액</th></tr></thead><tbody><tr v-for="stat in filteredStats" :key="stat.yearMonth"><td>{{stat.yearMonth}}</td><td>{{formatNumber(stat.monthlyRefCount)}}명</td><td><strong>{{formatNumber(stat.monthlyPurchase)}}원</strong></td></tr><tr v-if="!filteredStats.length"><td colspan="3" class="no-data">해당 기간의 활동 내역이 없습니다.</td></tr></tbody></table></div></div><div class="quick-links"><RouterLink to="/mypage/order-history"><i class="fa-solid fa-receipt"></i><span><strong>주문 내역</strong>최근 주문과 배송 상태 확인</span><i class="fa-solid fa-arrow-right"></i></RouterLink><RouterLink to="/mypage/inquiries"><i class="fa-regular fa-comments"></i><span><strong>문의 내역</strong>문의 답변과 처리 상태 확인</span><i class="fa-solid fa-arrow-right"></i></RouterLink></div></section></template>
<script setup>import{computed,onMounted,ref}from"vue";import UserService from"@/api/UserService";const stats=ref(null),selectedMonth=ref("전체");const user=JSON.parse(localStorage.getItem("user")||"null"),token=user?.token;const formatNumber=value=>Number(value||0).toLocaleString("ko-KR");const availableMonths=computed(()=>stats.value?[...new Set((stats.value.stats||[]).map(item=>item.yearMonth))].reverse():[]);const filteredStats=computed(()=>{if(!stats.value)return[];const list=[...(stats.value.stats||[])].reverse();return selectedMonth.value==="전체"?list:list.filter(item=>item.yearMonth===selectedMonth.value)});onMounted(async()=>{if(!user?._id)return;try{const response=await UserService.getUserStats(user._id,token);stats.value=response.data;if(response.data.token){user.token=response.data.token;localStorage.setItem("user",JSON.stringify(user))}}catch(error){console.error("활동 통계 로드 실패",error);stats.value={stats:[],totalRefCount:0,totalPurchase:0}}});</script>
<style>.mypage-dashboard{padding:34px;background:#fff;box-shadow:0 12px 40px rgba(55,38,47,.05)}.dashboard-head{display:flex;align-items:flex-end;justify-content:space-between;padding-bottom:26px;border-bottom:1px solid var(--color-line)}.dashboard-head h2{margin:6px 0 4px;font-family:Georgia,"Noto Serif KR",serif;font-size:2rem;font-weight:400}.dashboard-head>div>p:last-child{color:#958b90;font-size:.72rem}.dashboard-head label{display:flex;align-items:center;gap:10px;color:#746a6f;font-size:.68rem}.dashboard-head select{height:38px;padding:0 35px 0 12px;border:1px solid #ddd5d8;background:#fff;font-size:.7rem}.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:26px 0}.stat-grid article{position:relative;padding:22px;border:1px solid #e8e1de}.stat-grid article>span{width:34px;height:34px;display:grid;place-items:center;margin-bottom:18px;color:var(--color-brand);background:#f4edef}.stat-grid p{color:#8e8489;font-size:.66rem}.stat-grid strong{display:block;margin-top:5px;color:#3d3539;font-family:Georgia,"Noto Serif KR",serif;font-size:1.55rem;font-weight:400}.stat-grid small{margin-left:4px;font-family:inherit;font-size:.65rem}.activity-table{margin-top:10px}.activity-title{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.activity-title h3{font-size:.82rem}.activity-title span{color:#a1989c;font-size:.62rem}.activity-table thead{background:#f5f2f0;color:#665c61}.activity-table th,.activity-table td{padding:13px;text-align:center;border-bottom:1px solid #ebe5e2;font-size:.7rem}.activity-table td strong{color:var(--color-brand-dark)}.no-data{padding:45px!important;color:#9d9498}.quick-links{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:25px}.quick-links a{display:grid;grid-template-columns:30px 1fr 15px;align-items:center;padding:17px;border:1px solid #e8e1de;color:#8c8287}.quick-links a>i:first-child{color:var(--color-accent)}.quick-links span strong{display:block;color:#51484c;font-size:.72rem}.quick-links span{font-size:.6rem}.quick-links a>i:last-child{font-size:.6rem}.dashboard-loading{padding:70px;text-align:center;color:#8f858a;font-size:.7rem}.dashboard-loading span{display:block;width:28px;height:28px;margin:0 auto 12px;border:2px solid #eadfe2;border-top-color:var(--color-brand);border-radius:50%;animation:auth-spin .8s linear infinite}@media(max-width:700px){.mypage-dashboard{padding:24px 16px}.dashboard-head{align-items:flex-start;flex-direction:column;gap:18px}.stat-grid{grid-template-columns:1fr}.quick-links{grid-template-columns:1fr}.table-scroll{overflow-x:auto}.activity-table table{min-width:500px}}</style>
